-- Exact-current-client visual/resource catalog only. It does not authorize item-use mechanics.
CREATE TABLE IF NOT EXISTS `god2_game`.`client_item_effect_visuals` (
    `effect_id` int NOT NULL,
    `source_table` varchar(24) NOT NULL,
    `rom_resource_path` varchar(260) NULL,
    `rtg_resource_path` varchar(260) NULL,
    `sound_index` int NULL,
    `visual_description_original` varchar(500) NOT NULL,
    `visual_description_zh_tw` varchar(500) NOT NULL,
    `authored_mechanical_description_original` varchar(500) NULL,
    `authored_mechanical_description_zh_tw` varchar(500) NULL,
    `source_path` varchar(260) NOT NULL,
    `source_row` int NOT NULL,
    `source_sha256` char(64) NOT NULL,
    `evidence_status` varchar(64) NOT NULL,
    `mechanical_semantics_status` varchar(64) NOT NULL,
    `catalog_enabled` tinyint(1) NOT NULL DEFAULT 1,
    `runtime_eligible` tinyint(1) NOT NULL DEFAULT 0,
    `created_at_utc` datetime(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),
    `updated_at_utc` datetime(6) NOT NULL DEFAULT UTC_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (`effect_id`),
    KEY `ix_client_item_effect_visual_source` (`source_table`,`source_row`),
    CONSTRAINT `ck_client_item_effect_visual_catalog_enabled` CHECK (`catalog_enabled` IN (0,1)),
    CONSTRAINT `ck_client_item_effect_visual_runtime_blocked` CHECK (`runtime_eligible`=0),
    CONSTRAINT `ck_client_item_effect_visual_evidence` CHECK (`evidence_status`='VerifiedExactClientStaticVisualCatalog'),
    CONSTRAINT `ck_client_item_effect_visual_mechanics` CHECK (`mechanical_semantics_status`='DisplayTextOnlyServerAuthorityBlocked')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

