CREATE OR REPLACE VIEW `god2_game`.`vw_client_item_effect_visuals_readable` AS
SELECT `effect_id` AS `特效編號`,`source_table` AS `來源表`,`rom_resource_path` AS `ROM資源`,
       `rtg_resource_path` AS `RTG資源`,`sound_index` AS `音效索引`,`visual_description_original` AS `視覺原文`,
       `visual_description_zh_tw` AS `視覺繁中`,`authored_mechanical_description_original` AS `機械提示原文`,
       `authored_mechanical_description_zh_tw` AS `機械提示繁中`,`evidence_status` AS `靜態證據`,
       `mechanical_semantics_status` AS `服務端語意`,`runtime_eligible` AS `可執行`
FROM `god2_game`.`client_item_effect_visuals` WHERE `catalog_enabled`=1;
